pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, address receiver, uint256 amount) public {
        // admissible domain
        vm.assume(caller != address(0));
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);

        // record starting balance
        uint256 startBalance = address(c).balance;

        // deploy reverter to make adversarial transfers fail
        Reverter reverter = new Reverter();

        // deal enough ETH to c so transfers can succeed
        vm.deal(address(c), amount + 1 ether);
        startBalance = address(c).balance;

        // owner sends to reverter - this will revert, so c balance unchanged
        vm.prank(address(this));
        try c.sendTo(address(reverter), amount) {} catch {}

        // non-owner sends to receiver - this must never decrease c balance
        vm.prank(caller);
        try c.sendTo(receiver, amount) {} catch {}

        uint256 endBalance = address(c).balance;

        // rule: c's balance never falls below startBalance minus amounts sent by owner.
        // Since all owner calls in this test revert, startBalance is never legitimately reduced.
        // Any reduction is therefore a bug.
        assertTrue(endBalance >= startBalance);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

