import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address receiver, uint256 amount) public {
        // Ensure caller is not the owner; the owner is the setUp() deployer (this contract).
        vm.assume(caller != address(this));
        // Keep receiver and amount within valid domain to avoid interfering reverts.
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint256).max);

        // Set up call context: caller becomes msg.sender for the sendTo call.
        vm.prank(caller);

        // Observe whether sendTo reverts for a non-owner caller.
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }

        // Property: a non-owner caller must ALWAYS cause sendTo to revert.
        assertTrue(!ok);
    }
}

